// Resolve an addon description for a language, falling back to English and then
// to the raw constants.js desc (passed as `fallback`) so it never renders blank.
export const addonDesc = (id, lang, fallback) =>
  addonDescriptions[lang]?.[id] || addonDescriptions.en?.[id] || fallback;
